pragma solidity ^0.8.24;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ERC721Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC721/ERC721Upgradeable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {IDepositCertificate} from "./interfaces/IDepositCertificate.sol";

/// @title DepositCertificateUpgradeable
/// @notice ERC721 upgradable đại diện cho các sổ tiết kiệm (deposit certificates).
/// Mỗi depositId được map 1-1 với tokenId.
contract DepositCertificateUpgradeable is
    Initializable,
    ERC721Upgradeable,
    OwnableUpgradeable,
    IDepositCertificate
{
    /// @notice Địa chỉ SavingBank core được phép mint/burn.
    address public savingBankCore;

    error NotSavingBankCore();
    error ZeroAddress();

    /// @dev Initializer thay cho constructor.
    function initialize(
        string memory name_,
        string memory symbol_,
        address owner_
    ) public initializer {
        if (owner_ == address(0)) {
            revert ZeroAddress();
        }
        __ERC721_init(name_, symbol_);
        __Ownable_init(owner_);
    }

    /// @notice Thiết lập địa chỉ SavingBank core được phép mint/burn.
    /// Có thể set một lần sau khi deploy; nếu muốn đổi cần review security.
    function setSavingBankCore(address core) external onlyOwner {
        if (core == address(0)) {
            revert ZeroAddress();
        }
        savingBankCore = core;
    }

    modifier onlySavingBankCore() {
        if (msg.sender != savingBankCore) {
            revert NotSavingBankCore();
        }
        _;
    }

    /// @inheritdoc IDepositCertificate
    function mintCertificate(address to, uint256 depositId)
        external
        override
        onlySavingBankCore
    {
        _safeMint(to, depositId);
    }

    /// @inheritdoc IDepositCertificate
    function burnCertificate(uint256 depositId)
        external
        override
        onlySavingBankCore
    {
        _burn(depositId);
    }

    function ownerDepositCertificateOf(uint256 tokenId) 
        external 
        view 
        override
        returns (address) {
        return ownerOf(tokenId);
    }
}","keccak256":"0x7179f75f994e8c2db36d731b3321f6bbb826bbff6c3b582978f7a41350f3d0d3","license":"MIT"},"contracts/DepositRegistry.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IDepositRegistry} from "./interfaces/IDepositRegistry.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title DepositRegistry
/// @notice Lưu trữ toàn bộ trạng thái các sổ tiết kiệm (DepositInfo), tách biệt khỏi SavingBank core.
/// Chỉ các contract core được owner cho phép mới được ghi dữ liệu.
contract DepositRegistry is IDepositRegistry, Ownable {
    uint256 public override nextDepositId = 1;

    mapping(uint256 => DepositInfo) private _deposits;
    mapping(address => uint256) private _activeDepositOf;
    mapping(address => bool) public isBankCore;

    error NotAuthorizedCore();
    error InvalidOwner();
    error InvalidDeposit();
    error AlreadyHasActiveDeposit();
    error DepositNotActive();

    modifier onlyCore() {
        if (!isBankCore[msg.sender]) {
            revert NotAuthorizedCore();
        }
        _;
    }

    constructor() Ownable(msg.sender) {}

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------

    function setBankCore(address core, bool allowed) external onlyOwner {
        isBankCore[core] = allowed;
    }

    // ---------------------------------------------------------------------
    // Views
    // ---------------------------------------------------------------------

    function deposits(uint256 depositId) external view override returns (DepositInfo memory) {
        return _deposits[depositId];
    }

    function activeDepositOf(address user) external view override returns (uint256) {
        return _activeDepositOf[user];
    }

    function getActiveDepositId(address user) external view override returns (uint256) {
        return _activeDepositOf[user];
    }

    // ---------------------------------------------------------------------
    // Core write functions
    // ---------------------------------------------------------------------

    function createDeposit(
        address owner,
        uint256 planId,
        uint256 principal,
        uint32 tenorDays,
        uint32 aprBps,
        uint32 earlyWithdrawPenaltyBps,
        uint64 startAt,
        uint64 maturityAt
    ) external override onlyCore returns (uint256 depositId) {
        if (owner == address(0)) {
            revert InvalidOwner();
        }
        if (_activeDepositOf[owner] != 0) {
            revert AlreadyHasActiveDeposit();
        }
        depositId = nextDepositId;
        nextDepositId = depositId + 1;

        _deposits[depositId] = DepositInfo({
            id: depositId,
            planId: planId,
            owner: owner,
            principal: principal,
            tenorDays: tenorDays,
            aprBps: aprBps,
            earlyWithdrawPenaltyBps: earlyWithdrawPenaltyBps,
            startAt: startAt,
            maturityAt: maturityAt,
            status: DepositStatus.Active
        });

        _activeDepositOf[owner] = depositId;
    }

    function markWithdrawn(uint256 depositId) external override onlyCore {
        DepositInfo storage dep = _deposits[depositId];
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (dep.status != DepositStatus.Active) {
            revert DepositNotActive();
        }

        dep.status = DepositStatus.Withdrawn;
        if (_activeDepositOf[dep.owner] == depositId) {
            _activeDepositOf[dep.owner] = 0;
        }
    }

    function markEarlyWithdrawn(uint256 depositId) external override onlyCore {
        DepositInfo storage dep = _deposits[depositId];
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (dep.status != DepositStatus.Active) {
            revert DepositNotActive();
        }

        dep.status = DepositStatus.EarlyWithdrawn;
        if (_activeDepositOf[dep.owner] == depositId) {
            _activeDepositOf[dep.owner] = 0;
        }
    }

    function markRenewed(uint256 depositId) external override onlyCore {
        DepositInfo storage dep = _deposits[depositId];
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (dep.status != DepositStatus.Active) {
            revert DepositNotActive();
        }

        dep.status = DepositStatus.Renewed;
        if (_activeDepositOf[dep.owner] == depositId) {
            _activeDepositOf[dep.owner] = 0;
        }
    }

    function createRenewedDeposit(
        address owner,
        uint256 newPlanId,
        uint256 newPrincipal,
        uint32 tenorDays,
        uint32 aprBps,
        uint32 earlyWithdrawPenaltyBps,
        uint64 startAt,
        uint64 maturityAt
    ) external override onlyCore returns (uint256 newDepositId) {
        if (owner == address(0)) {
            revert InvalidOwner();
        }
        // cho phép ghi đè activeDepositOf (user có đúng 1 sổ active sau renew)
        newDepositId = nextDepositId;
        nextDepositId = newDepositId + 1;

        _deposits[newDepositId] = DepositInfo({
            id: newDepositId,
            planId: newPlanId,
            owner: owner,
            principal: newPrincipal,
            tenorDays: tenorDays,
            aprBps: aprBps,
            earlyWithdrawPenaltyBps: earlyWithdrawPenaltyBps,
            startAt: startAt,
            maturityAt: maturityAt,
            status: DepositStatus.Active
        });

        _activeDepositOf[owner] = newDepositId;
    }
}
