pragma solidity ^0.8.24;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IDepositCertificate} from "./interfaces/IDepositCertificate.sol";
import {IDepositRegistry} from "./interfaces/IDepositRegistry.sol";
import {ISavingBankCore} from "./interfaces/ISavingBankCore.sol";

/// @title SavingBankUpgradeable
/// @notice Core logic sản phẩm tiết kiệm có kỳ hạn, tách riêng khỏi ERC721 certificate.
/// Implement các interface nhỏ: ISavingPlanManager, IVaultManager, IDepositManager thông qua ISavingBankCore.
contract SavingBankUpgradeable is
    Initializable,
    OwnableUpgradeable,
    PausableUpgradeable,
    ReentrancyGuardUpgradeable,
    ISavingBankCore
{
    using SafeERC20 for IERC20;

    /// @dev Maximum APR in basis points (e.g. 5000 = 50%).
    uint32 public constant MAX_APR_BPS = 5000;

    /// @dev Maximum penalty in basis points (10000 = 100%).
    uint32 public constant MAX_PENALTY_BPS = 10000;

    IERC20 public token;
    IDepositRegistry public registry;
    IDepositCertificate public certificate;

    /// @notice Address receiving early-withdrawal penalties (can be zero address => penalties stay in vault).
    address public feeReceiver;

    /// @notice Balance of the liquidity vault used to pay interest.
    uint256 public vaultBalance;

    uint256 public nextPlanId;

    struct SavingPlan {
        uint256 id;
        uint32 tenorDays;
        uint32 aprBps;
        uint256 minDeposit;
        uint256 maxDeposit; // 0 = unlimited
        uint32 earlyWithdrawPenaltyBps;
        bool enabled;
    }

    mapping(uint256 => SavingPlan) public plans;
    // Deposit state được lưu trữ trong DepositRegistry

   
    // ---------------------------------------------------------------------
    // Errors
    // ---------------------------------------------------------------------

    error ZeroAddress();
    error InvalidPlan();
    error InvalidDeposit();
    error PlanDisabled();
    error InvalidAmount();
    error InvalidParameters();
    error NotDepositOwner();
    error DepositNotActive();
    error NotMatured();
    error AlreadyMatured();
    error InsufficientVault();
    error AlreadyHasActiveDeposit();

    // ---------------------------------------------------------------------
    // Initializer
    // ---------------------------------------------------------------------

    /// @notice Khởi tạo contract upgradable, thay cho constructor.
    /// @param token_ Địa chỉ ERC20 dùng làm stablecoin gửi tiết kiệm.
    /// @param registry_ Địa chỉ DepositRegistry lưu state deposit.
    /// @param certificate_ Địa chỉ ERC721 certificate contract.
    /// @param owner_ Owner của SavingBank core.
    function initialize(
        address token_,
        address registry_,
        address certificate_,
        address owner_
    ) external initializer {
        if (token_ == address(0) || registry_ == address(0) || certificate_ == address(0) || owner_ == address(0)) {
            revert ZeroAddress();
        }

        __Ownable_init(owner_);
        __Pausable_init();
        __ReentrancyGuard_init();

        token = IERC20(token_);
        registry = IDepositRegistry(registry_);
        certificate = IDepositCertificate(certificate_);
        feeReceiver = owner_;

        nextPlanId = 1;
    }

    // ---------------------------------------------------------------------
    // Admin: Saving Plans
    // ---------------------------------------------------------------------

    function createPlan(
        uint32 tenorDays,
        uint32 aprBps,
        uint256 minDeposit,
        uint256 maxDeposit,
        uint32 earlyWithdrawPenaltyBps,
        bool enabled
    ) external onlyOwner {
        if (tenorDays == 0) {
            revert InvalidParameters();
        }
        if (aprBps > MAX_APR_BPS) {
            revert InvalidParameters();
        }
        if (earlyWithdrawPenaltyBps > MAX_PENALTY_BPS) {
            revert InvalidParameters();
        }
        if (maxDeposit != 0 && maxDeposit < minDeposit) {
            revert InvalidParameters();
        }

        uint256 planId = nextPlanId++;

        plans[planId] = SavingPlan({
            id: planId,
            tenorDays: tenorDays,
            aprBps: aprBps,
            minDeposit: minDeposit,
            maxDeposit: maxDeposit,
            earlyWithdrawPenaltyBps: earlyWithdrawPenaltyBps,
            enabled: enabled
        });

        emit PlanCreated(
            planId,
            tenorDays,
            aprBps,
            minDeposit,
            maxDeposit,
            earlyWithdrawPenaltyBps,
            enabled
        );
    }

    function updatePlan(
        uint256 planId,
        uint32 tenorDays,
        uint32 aprBps,
        uint256 minDeposit,
        uint256 maxDeposit,
        uint32 earlyWithdrawPenaltyBps,
        bool enabled
    ) external onlyOwner {
        SavingPlan storage plan = plans[planId];
        if (plan.id == 0) {
            revert InvalidPlan();
        }
        if (tenorDays == 0) {
            revert InvalidParameters();
        }
        if (aprBps > MAX_APR_BPS) {
            revert InvalidParameters();
        }
        if (earlyWithdrawPenaltyBps > MAX_PENALTY_BPS) {
            revert InvalidParameters();
        }
        if (maxDeposit != 0 && maxDeposit < minDeposit) {
            revert InvalidParameters();
        }

        plan.tenorDays = tenorDays;
        plan.aprBps = aprBps;
        plan.minDeposit = minDeposit;
        plan.maxDeposit = maxDeposit;
        plan.earlyWithdrawPenaltyBps = earlyWithdrawPenaltyBps;
        plan.enabled = enabled;

        emit PlanUpdated(
            planId,
            tenorDays,
            aprBps,
            minDeposit,
            maxDeposit,
            earlyWithdrawPenaltyBps,
            enabled
        );
    }

    // ---------------------------------------------------------------------
    // Admin: Vault & Fee Receiver
    // ---------------------------------------------------------------------

    function setFeeReceiver(address newFeeReceiver) external onlyOwner {
        feeReceiver = newFeeReceiver;
        emit FeeReceiverUpdated(newFeeReceiver);
    }

    /// @notice Fund the interest vault; tokens must be approved beforehand.
    function fundVault(uint256 amount) external onlyOwner {
        if (amount == 0) {
            revert InvalidAmount();
        }
        token.safeTransferFrom(msg.sender, address(this), amount);
        vaultBalance += amount;
        emit VaultFunded(msg.sender, amount);
    }

    /// @notice Withdraw from the interest vault (cannot withdraw user principals).
    function withdrawVault(uint256 amount) external onlyOwner {
        if (amount == 0) {
            revert InvalidAmount();
        }
        if (amount > vaultBalance) {
            revert InsufficientVault();
        }
        vaultBalance -= amount;
        token.safeTransfer(msg.sender, amount);
        emit VaultWithdrawn(msg.sender, amount);
    }

    // ---------------------------------------------------------------------
    // Admin: Pause
    // ---------------------------------------------------------------------

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // ---------------------------------------------------------------------
    // User actions
    // ---------------------------------------------------------------------

    function openDeposit(uint256 planId, uint256 amount)
        external
        whenNotPaused
        nonReentrant
        returns (uint256 depositId)
    {
        SavingPlan storage plan = plans[planId];
        if (plan.id == 0) {
            revert InvalidPlan();
        }
        if (!plan.enabled) {
            revert PlanDisabled();
        }
        if (amount == 0) {
            revert InvalidAmount();
        }
        if (amount < plan.minDeposit) {
            revert InvalidAmount();
        }
        if (plan.maxDeposit != 0 && amount > plan.maxDeposit) {
            revert InvalidAmount();
        }

        if (registry.getActiveDepositId(msg.sender) != 0) {
            revert AlreadyHasActiveDeposit();
        }

        token.safeTransferFrom(msg.sender, address(this), amount);

        uint64 startAt = uint64(block.timestamp);
        uint64 maturityAt = uint64(block.timestamp + uint64(plan.tenorDays) * 1 days);
        depositId = registry.createDeposit(
            msg.sender,
            planId,
            amount,
            plan.tenorDays,
            plan.aprBps,
            plan.earlyWithdrawPenaltyBps,
            startAt,
            maturityAt
        );

        certificate.mintCertificate(msg.sender, depositId);

        emit DepositOpened(depositId, msg.sender, planId, amount, maturityAt);
    }

    /// @notice Withdraw at or after maturity, receiving principal + interest.
    function withdrawAtMaturity(uint256 depositId)
        external
        whenNotPaused
        nonReentrant
    {
        IDepositRegistry.DepositInfo memory dep = registry.deposits(depositId);
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (msg.sender != dep.owner) {
            revert NotDepositOwner();
        }

        if (dep.status != IDepositRegistry.DepositStatus.Active) {
            revert DepositNotActive();
        }
        if (block.timestamp < dep.maturityAt) {
            revert NotMatured();
        }

        uint256 interest = _calculateInterest(
            dep.principal,
            dep.aprBps,
            dep.tenorDays
        );

        if (interest > vaultBalance) {
            revert InsufficientVault();
        }

        vaultBalance -= interest;

        registry.markWithdrawn(depositId);
        certificate.burnCertificate(depositId);

        address owner_ = dep.owner;
        uint256 principal = dep.principal;
        uint256 payout = principal + interest;

        token.safeTransfer(owner_, payout);

        emit Withdrawn(depositId, owner_, principal, interest, false);
    }

    /// @notice Early withdraw before maturity, receiving principal minus penalty.
    function earlyWithdraw(uint256 depositId)
        external
        whenNotPaused
        nonReentrant
    {
        IDepositRegistry.DepositInfo memory dep = registry.deposits(depositId);
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (msg.sender != dep.owner) {
            revert NotDepositOwner();
        }

        if (dep.status != IDepositRegistry.DepositStatus.Active) {
            revert DepositNotActive();
        }
        if (block.timestamp >= dep.maturityAt) {
            revert AlreadyMatured();
        }

        uint256 penalty = (dep.principal * dep.earlyWithdrawPenaltyBps) / 10000;
        if (penalty > dep.principal) {
            penalty = dep.principal;
        }
        uint256 userAmount = dep.principal - penalty;

        registry.markEarlyWithdrawn(depositId);
        certificate.burnCertificate(depositId);

        address owner_ = dep.owner;
        token.safeTransfer(owner_, userAmount);

        if (penalty > 0) {
            if (feeReceiver != address(0)) {
                token.safeTransfer(feeReceiver, penalty);
            } else {
                // keep penalty inside contract and treat as part of vault
                vaultBalance += penalty;
            }
        }

        emit Withdrawn(depositId, owner_, dep.principal, 0, true);
    }

    /// @notice Renew a matured deposit into a new plan, rolling over principal + interest.
    function renewDeposit(uint256 depositId, uint256 newPlanId)
        external
        whenNotPaused
        nonReentrant
        returns (uint256 newDepositId)
    {
        IDepositRegistry.DepositInfo memory dep = registry.deposits(depositId);
        if (dep.id == 0 || dep.owner == address(0)) {
            revert InvalidDeposit();
        }
        if (msg.sender != dep.owner) {
            revert NotDepositOwner();
        }

        if (dep.status != IDepositRegistry.DepositStatus.Active) {
            revert DepositNotActive();
        }
        if (block.timestamp < dep.maturityAt) {
            revert NotMatured();
        }

        SavingPlan storage newPlan = plans[newPlanId];
        if (newPlan.id == 0) {
            revert InvalidPlan();
        }
        if (!newPlan.enabled) {
            revert PlanDisabled();
        }

        uint256 interest = _calculateInterest(
            dep.principal,
            dep.aprBps,
            dep.tenorDays
        );

        if (interest > vaultBalance) {
            revert InsufficientVault();
        }

        vaultBalance -= interest;

        uint256 newPrincipal = dep.principal + interest;

        if (newPrincipal < newPlan.minDeposit) {
            revert InvalidAmount();
        }
        if (newPlan.maxDeposit != 0 && newPrincipal > newPlan.maxDeposit) {
            revert InvalidAmount();
        }

        address owner_ = dep.owner;
        uint64 startAt = uint64(block.timestamp);
        uint64 maturityAt = uint64(block.timestamp + uint64(newPlan.tenorDays) * 1 days);
        registry.markRenewed(depositId);
        certificate.burnCertificate(depositId);

        newDepositId = registry.createRenewedDeposit(
            owner_,
            newPlanId,
            newPrincipal,
            newPlan.tenorDays,
            newPlan.aprBps,
            newPlan.earlyWithdrawPenaltyBps,
            startAt,
            maturityAt
        );

        certificate.mintCertificate(owner_, newDepositId);

        emit Renewed(depositId, newDepositId, newPrincipal);
    }

    /// @notice Get the active deposit ID of the caller (0 if none).
    function getMyActiveDepositId() external view returns (uint256) {
        return registry.getActiveDepositId(msg.sender);
    }

    /// @notice Get the active deposit ID of a user (0 if none).
    function getActiveDepositId(address user) external view returns (uint256) {
        return registry.getActiveDepositId(user);
    }

    function _calculateInterest(
        uint256 principal,
        uint32 aprBps,
        uint32 tenorDays
    ) internal pure returns (uint256) {
        if (principal == 0 || aprBps == 0 || tenorDays == 0) {
            return 0;
        }
        uint256 tenorSeconds = uint256(tenorDays) * 1 days;
        uint256 yearInSeconds = 365 days;
        // interest = principal * aprBps * tenorSeconds / (365 days * 10000)
        return (principal * aprBps * tenorSeconds) / (yearInSeconds * 10000);
    }
}","keccak256":"0x4e50de3261ed17be391224480ec6489201ce76bd60f5a710714c5780a4257f23","license":"MIT"},"contracts/SavingBankUpgradeableFactory.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {SavingBankUpgradeable} from "./SavingBankUpgradeable.sol";
import {DepositRegistry} from "./DepositRegistry.sol";
import {DepositCertificateUpgradeable} from "./DepositCertificateUpgradeable.sol";

/// @dev Interface tối giản để đọc owner từ các contract Ownable/OwnableUpgradeable.
    interface IOwnableLike {
        function owner() external view returns (address);
    }

/// @title SavingBankUpgradeableFactory
/// @notice Factory tạo ra cặp contract SavingBankCoreUpgradeable + DepositCertificateUpgradeable
/// cho từng ERC20 token, bám sát kiến trúc tách core logic và ERC721 certificate.
contract SavingBankUpgradeableFactory is Ownable {
    struct BankDeployment {
        address core;          // SavingBankCoreUpgradeable
        address registry;      // DepositRegistry (state holder)
        address certificate;   // DepositCertificateUpgradeable (ERC721)
        address token;         // ERC20 underlying
        address creator;       // Người tạo bank
    }

    /// @notice Danh sách tất cả bank (core + certificate) đã tạo.
    BankDeployment[] public allBanks;

    /// @notice Mapping creator -> danh sách địa chỉ core bank họ tạo.
    mapping(address => address[]) public userBanks;

    /// @notice Đánh dấu một địa chỉ có phải core bank được tạo bởi factory hay không.
    mapping(address => bool) public isBankCore;

    event SavingBankCreated(
        address indexed creator,
        address indexed core,
        address indexed registry,
        address certificate,
        address token,
        string name,
        string symbol
    );

    constructor() Ownable(msg.sender) {}

    

    /// @notice Tạo mới một SavingBank upgradable cho một ERC20 token.
    /// @param token ERC20 token dùng làm stablecoin gửi tiết kiệm.
    /// @param name_ Tên collection ERC721 cho sổ tiết kiệm (NFT certificate).
    /// @param symbol_ Symbol collection ERC721.
    /// @return core Địa chỉ SavingBankCoreUpgradeable mới.
    /// @return registry Địa chỉ DepositRegistry mới.
    /// @return certificate Địa chỉ DepositCertificateUpgradeable mới.
    function createSavingBank(
        IERC20 token,
        string memory name_,
        string memory symbol_
    ) external returns (address core, address registry, address certificate) {
        require(address(token) != address(0), "TOKEN_ZERO");

        // 1. Deploy registry lưu state deposit, owner = factory để cấu hình quyền core.
        DepositRegistry reg = new DepositRegistry();

        // 2. Deploy certificate (ERC721). Tạm thời set owner = factory để cấu hình, sau đó chuyển lại cho creator.
        DepositCertificateUpgradeable cert = new DepositCertificateUpgradeable();
        cert.initialize(name_, symbol_, address(this));

        // 3. Deploy core logic contract
        SavingBankUpgradeable coreContract = new SavingBankUpgradeable();
        coreContract.initialize(address(token), address(reg), address(cert), msg.sender);

        // 4. Liên kết core với registry & certificate
        reg.setBankCore(address(coreContract), true);
        cert.setSavingBankCore(address(coreContract));

        // 5. Chuyển quyền owner certificate + registry lại cho creator để họ quản trị
        cert.transferOwnership(msg.sender);
        reg.transferOwnership(msg.sender);

        core = address(coreContract);
        registry = address(reg);
        certificate = address(cert);

        allBanks.push(
            BankDeployment({
                core: core,
                registry: registry,
                certificate: certificate,
                token: address(token),
                creator: msg.sender
            })
        );

        userBanks[msg.sender].push(core);
        isBankCore[core] = true;

        emit SavingBankCreated(
            msg.sender,
            core,
            registry,
            certificate,
            address(token),
            name_,
            symbol_
        );
    }

    /// @notice Tạo core SavingBank mới tái sử dụng lại registry + NFT certificate cũ.
    /// @dev Dùng trong trường hợp muốn thay thế core nhưng vẫn giữ nguyên state và NFT.
    /// Người gọi PHẢI là owner của cả registry và certificate, và sau khi tạo xong
    /// cần tự gọi:
    ///  - DepositRegistry(registry).setBankCore(core, true)
    ///  - DepositCertificateUpgradeable(certificate).setSavingBankCore(core)
    /// để gán quyền cho core mới.
    /// @param token ERC20 token dùng làm stablecoin.
    /// @param registry Địa chỉ DepositRegistry đã tồn tại.
    /// @param certificate Địa chỉ DepositCertificateUpgradeable (NFT) đã tồn tại.
    /// @return core Địa chỉ SavingBankCoreUpgradeable mới.
    function createSavingBankWithExistingState(
        IERC20 token,
        address registry,
        address certificate
    ) external returns (address core) {
        require(address(token) != address(0), "TOKEN_ZERO");
        require(registry != address(0), "REG_ZERO");
        require(certificate != address(0), "CERT_ZERO");

        // Đảm bảo caller là owner của cả registry và certificate
        require(IOwnableLike(registry).owner() == msg.sender, "NOT_REG_OWNER");
        require(IOwnableLike(certificate).owner() == msg.sender, "NOT_CERT_OWNER");

        // Deploy core mới, trỏ tới registry + certificate cũ
        SavingBankUpgradeable coreContract = new SavingBankUpgradeable();
        coreContract.initialize(address(token), registry, certificate, msg.sender);

        core = address(coreContract);

        allBanks.push(
            BankDeployment({
                core: core,
                registry: registry,
                certificate: certificate,
                token: address(token),
                creator: msg.sender
            })
        );

        userBanks[msg.sender].push(core);
        isBankCore[core] = true;

        // Lấy lại name/symbol từ NFT cũ để emit event cho thuận tiện theo dõi.
        string memory name_ = DepositCertificateUpgradeable(certificate).name();
        string memory symbol_ = DepositCertificateUpgradeable(certificate).symbol();

        emit SavingBankCreated(
            msg.sender,
            core,
            registry,
            certificate,
            address(token),
            name_,
            symbol_
        );
    }

    /// @notice Số lượng bank đã được tạo qua factory.
    function allBanksLength() external view returns (uint256) {
        return allBanks.length;
    }

    /// @notice Lấy danh sách địa chỉ core bank do một user tạo.
    function getUserBanks(address user) external view returns (address[] memory) {
        return userBanks[user];
    }

    /// @notice Lấy thông tin triển khai bank theo index.
    function getBankDeployment(uint256 index)
        external
        view
        returns (address core, address registry, address token, address creator)
    {
        require(index < allBanks.length, "INDEX_OUT_OF_BOUNDS");
        BankDeployment storage b = allBanks[index];
        return (b.core, b.registry, b.token, b.creator);
    }
